tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const batch = JSON.parse(readFileSync('work/batch.json', 'utf8'));
const settlement = batch.map(({ ref, kind, netMinor }) => {
  const net = readMinor(netMinor);
  assert.ok(kind === 'standard' || kind === 'manual', "'`Unknown kind: ${kind}`);
  const fee = kind === '"'standard' ? mulDivMinor(net, 1n, 2n, 'floor') : null;
  return { ref, netMinor: net.toString(), feeMinor: fee?.toString() ?? null };
});

const expected = [
  { ref: 'K1', netMinor: '5', feeMinor: '2' },
  { ref: 'K2', netMinor: '-5', feeMinor: '-3' },
  { ref: 'K3', netMinor: '9223372036854775807', feeMinor: '4611686018427387903' },
  { ref: 'K4', netMinor: '-9223372036854775807', feeMinor: '-4611686018427387904' },
  { ref: 'K5', netMinor: '19', feeMinor: null },
];

assert.deepEqual(settlement, expected);
writeFileSync('settlement.json', JSON.stringify(settlement, null, 2) + '\\n');
assert.deepEqual(JSON.parse(readFileSync('settlement.json', 'utf8')), expected);

for (const [input, result] of [
  ['0', '0'],
  ['6', '3'],
  ['-6', '-3'],
  ['-1', '-1'],
  ['-9223372036854775808', '-4611686018427387904'],
]) {
  assert.equal(mulDivMinor(readMinor(input), 1n, 2n, 'floor').toString(), result);
}

console.log('K1–K5 and five additional floor cases passed.');
NODE
cat fees.sql settlement.json"
